var e={name:"Nam Nguyen",headline:"Lead front-end developer",target:"Senior Software Engineer, Web Development",targetAlt:"Senior Front-End Engineer, Web",place:"Uppsala, Sweden",commute:"38 minutes from the Stockholm office. No relocation, no visa sponsorship needed.",emailUser:"hainam2511",emailHost:"gmail.com",links:[{label:"GitHub",handle:"southocean",href:"https://github.com/southocean"},{label:"LinkedIn",handle:"southocean",href:"https://www.linkedin.com/in/southocean"},{label:"itch.io",handle:"southocean",href:"https://southocean.itch.io"}],languages:"Vietnamese (native) \xB7 English C2 \xB7 Swedish C1"},t="2026-08-20",a="https://southocean.github.io/callback/",n="I have spent seven years leading the front end of a real-time multiplayer client \u2014 shared state, reconnection, latency, a rendering engine embedded in a web app. That is the same shape of problem as a video call.",r=[{id:"mahjong",org:"Wasabi Productions",title:"Lead front-end developer",from:2019.25,to:null,fromLabel:"Apr 2019",toLabel:"present",place:"Uppsala, Sweden",kind:"engineering",gist:"Seven years on a real-time multiplayer game client. The closest thing on this CV to a video call.",bullets:["Game client for online mahjong, built for the Chinese and Japanese markets.","Pivoted the product through every platform it has had: web app, to Unity, and now React Native serving both web and mobile.","Pioneered agentic programming at the company \u2014 built the cross-team AI harnesses and drove adoption beyond my own team.","Feature design, UX and responsive design, advanced Mahjong bot design (4\u20135 Dan), the bot swarm controller, and automated QA.","Worked directly with designers, backend, marketing and investors \u2014 a vertical grasp of the whole product, and an active say in what gets built next."]},{id:"research",org:"D&A Research",title:"Data and algorithms research",from:2014,to:2018.85,fromLabel:"2014",toLabel:"2018",place:"Uppsala \xB7 Hanoi",kind:"research",gist:"Graph mining and combinatorial optimisation. This is where the algorithms came from.",bullets:["Graph mining, contributed to the Multinet open-source library \u2014 InfoLab, Uppsala University, 2018.","Sensor network optimisation: two publications, one book chapter, one best-paper award \u2014 MSO Lab, HUST, 2014\u20132017."]},{id:"bkav",org:"Bkav Corp.",title:"C++ developer",from:2013.7,to:2015.85,fromLabel:"Sep 2013",toLabel:"Nov 2015",place:"Hanoi, Vietnam",kind:"engineering",gist:"Security tokens in C++. Where getting it exactly right was the whole job.",bullets:["Researched and built eToken, a hardware security token for signing and verifying digital signatures.","Delivered a beta version meeting the relevant ISO standards."]}],i=[{id:"mahjong",title:"A real-time multiplayer client, through two platform migrations",org:"Mahjong Logic",years:"2019 \u2014 present",stack:["JavaScript","React","Unity","C#","REST APIs","responsive UI"],problem:"Four players at a table, in different countries, on different networks, all of whom must see the same board at the same moment. One of them is on hotel wifi. The client has to stay honest about shared state while the connection underneath it is not honest at all.",approach:["Took the product from a native desktop app to the browser, then to a hybrid client running React for interface and Unity for the table itself \u2014 embedding a rendering engine inside a web app and keeping the two in step.","Designed the API surface between client and server, which is where the reconnection and resync behaviour actually lives.","Built a bot controller so live tables could be driven under test instead of by hand. Test automation for a system whose hardest bugs only appear with four real participants.","Localised for the Chinese and Japanese markets, where the game conventions and the typography both differ.","Led five engineers: split the work, ran the reviews, and defended the architecture to designers, marketing and investors."],relevance:"A conferencing client is this problem with media attached. Shared session state, participants joining and dropping, a resync that must not lose the room, and a rendering surface inside a web app that cannot be allowed to drop frames. I have been shipping that for seven years, in a browser."},{id:"callback",title:"This site",org:"Callback",years:"2026",stack:["TypeScript","WebGL","Web Audio","zero dependencies"],problem:"The Meet roles ask for TypeScript, test automation and accessible technologies. Claiming all three on a PDF is free, so a claim is worth nothing. The artifact had to be the evidence.",approach:["Strict TypeScript, no framework, no runtime dependencies. The whole bundle is under the budget printed in the footer, and the build fails if it goes over.","A real unit-test suite over real logic \u2014 the state reducer, timeline geometry, the caption scheduler, the network model. It runs in CI and it runs in your browser, in the Engineering panel.","A chaos switch in that panel injects a fault so you can watch the suite go red. A green screenshot proves nothing.","A WebGL filter chain over live video, because effects are a feature this product ships and building one is more convincing than mentioning one.","A network simulator that degrades the call: loss, jitter, resolution collapse. The failure mode this team actually lives in.","Accessibility done as work rather than as a bullet: roving tabindex, focus traps, reduced-motion, and an audit panel that asserts against the live DOM and is allowed to fail.","Built with agentic tooling and the build log left in, since the senior posting asks for exactly that."],relevance:"Every requirement in the job ad has something here you can click on. That was the entire design brief."},{id:"etoken",title:"eToken \u2014 signing hardware, in C++",org:"Bkav Corp.",years:"2013 \u2014 2015",stack:["C++","cryptographic signing","ISO conformance"],problem:'A device that signs documents has no acceptable margin of error and no useful way to say "roughly".',approach:["Researched and implemented the token that signs and verifies digital signatures.","Drove it to a beta meeting the relevant ISO standards \u2014 conformance as the definition of done, rather than a phase at the end."],relevance:"Two years in a codebase where correctness was the product. It is the reason I write tests before I am asked to."},{id:"research",title:"Combinatorial optimisation, published",org:"MSO Lab, HUST \xB7 InfoLab, Uppsala",years:"2014 \u2014 2018",stack:["algorithms","genetic algorithms","graph mining","Matlab","Python"],problem:"Where to place sensors, how to route between them, and how to find a good answer when the exact one is out of reach.",approach:["Three years of wireless sensor network optimisation at MSO Lab. Two publications, a book chapter, and a best-paper award at IEEE R10-HTC.","Grant co-holder for IEEE AIYEHUM 2016 and 2017 and IEEE R-10 HTA 2017.","Master's thesis on graph mining over Twitter, contributed to the Multinet open-source library.","Taught the algorithms too: teaching assistant for Genetic Algorithms, Database Design and Advanced Software Design."],relevance:"Both postings list data structures and algorithms as preferred. This is not a weekend of practice problems \u2014 it is four years of it, peer-reviewed, and three semesters of teaching it to other people."}],o=[{from:"system",at:"",text:"Nam started a call. This panel is the cover letter \u2014 he just refused to attach it as a .docx."},{from:"nam",at:"09:00",text:"Hi. I'm Nam, I live in Uppsala, and I am applying for a senior web development role."},{from:"nam",at:"09:00",text:"The short version: seven years leading the front end of a real-time multiplayer client. Four strangers on four networks who all have to see the same board at the same instant, one of them on hotel wifi. Take that and attach media to it and you have roughly your product."},{from:"nam",at:"09:01",text:"I took that client from a desktop app to the browser, then to a React + Unity hybrid \u2014 a rendering engine living inside a web page, which is a sentence I understand the cost of. I led the five people who did it with me."},{from:"nam",at:"09:02",text:"Before that: two years of C++ on signing hardware, where correctness was the product. Before that, four years of optimisation research \u2014 two papers, a book chapter, a best-paper award, and three semesters as a teaching assistant for algorithms. Your ad asks for data structures and algorithms. That part I can show you."},{from:"nam",at:"09:03",text:"One thing I will not pretend about: accessibility is listed as preferred and I have not shipped a product where it was my mandate. So I did the work here instead \u2014 this page is keyboard-complete, screen-reader tested, and the Engineering panel audits it live and is allowed to fail. Judge it on that."},{from:"nam",at:"09:04",text:"Your posting mentions agentic coding. I built this with it, and left the build log in the Engineering panel \u2014 including three rounds of people picking the plan apart, and what I changed each time."},{from:"nam",at:"09:05",text:"Also, and this is relevant more than it sounds: I do stand-up. Seven years of walking into a room cold and finding out in ten seconds whether a thing lands. That is the same instinct a UX review needs."},{from:"nam",at:"09:06",text:"I'm 38 minutes from your office, I speak Swedish at C1, and I already have the right to work here. End the call whenever you like \u2014 there is a PDF and an email address on the way out."}],s=[{at:0,speaker:"Nam",text:"Thanks for joining. I know a CV that opens a call is a bit much."},{at:4,speaker:"Nam",text:"So let me be quick about why I'm in your applicant pool."},{at:8,speaker:"Nam",text:"Seven years leading the front end of a real-time multiplayer client."},{at:13,speaker:"Nam",text:"Four players, four networks, one shared board, no excuses about latency."},{at:18,speaker:"Nam",text:"Desktop, then web, then a Unity renderer embedded in a React app."},{at:23,speaker:"Nam",text:"A team of five, and the design reviews to go with it."},{at:27,speaker:"Nam",text:"Before that, C++ on signing hardware. Correctness was the product."},{at:32,speaker:"Nam",text:"Before that, four years of optimisation research and a best-paper award."},{at:37,speaker:"Nam",text:"This page is TypeScript, no framework, no dependencies, under budget."},{at:42,speaker:"Nam",text:"The tests are real, they run in your browser, and you can break them."},{at:47,speaker:"Nam",text:"I live 38 minutes away and I speak Swedish. Your move."}],h={primary:[{name:"React \xB7 Unity \xB7 Flutter",note:"the three frameworks the product has shipped on, across three platform migrations"},{name:"Agentic programming",note:"cross-team AI harnesses at Wasabi, and this entire site \u2014 built in a week by one person and an agent"},{name:"Test automation",note:"75\u201390% unit coverage, AI-assisted, plus automated QA over the core UI flows"},{name:"Real-time clients",note:"shared state, reconnection and latency on a live multiplayer game \u2014 the same shape of problem as a video call"},{name:"Responsive & accessible UI",note:"this page: roving tabindex, live regions, reduced-motion, keyboard-only paths, audited rather than assumed"},{name:"Performance budgets",note:"an initial-load ceiling enforced in CI, so it cannot rot between releases"}],volume:{"Over 10,000 lines":["TypeScript","JavaScript","C","C++","C#","Dart","Java"],"Over 1,000 lines":["Erlang","SQL","Python","Matlab","R","PHP"],"Tools & platforms":["Figma","UML","Spark","MySQL","Git","Unity Editor"]}},l=[{school:"Uppsala University",award:"MSc, Computer Science",years:"2016 \u2014 2018",place:"Uppsala, Sweden"},{school:"Tokyo University of Agriculture and Technology",award:"Research exchange",years:"2015",place:"Tokyo, Japan"},{school:"Hanoi University of Science and Technology",award:"BS, Computer Science",years:"2011 \u2014 2016",place:"Hanoi, Vietnam"}],d=["Database Design (HT16, HT17)","Advanced Software Design (HT17)","Genetic Algorithms (2014 \u2014 2015)"],c={items:[{what:"Stand-up comedy",why:"Performed at Fyris Komedi and Comedy Nation. Competed in Uppsalas Roligaste 2026."},{what:"Acting",why:"Short films: Tomma H\xE4nder (.MOV Filmfestival 2026), The Darkest Hour, Don\u2019t Cry Over Spilled Milk."},{what:"Uppsala Zombie Walk organiser",why:"Website, marketing, makeup, logistics and the rest of it. Featured on SVT and UNT.",href:"https://www.svt.se/nyheter/lokalt/uppsala/zombie-walk-i-uppsala",hrefLabel:"SVT"},{what:"Sports",why:"Swimming and Brazilian jiu-jitsu."}]},p=[{req:"Bachelor's degree or equivalent",evidence:"BS Computer Science, HUST. MSc Computer Science, Uppsala.",strength:"strong"},{req:"5 years software development",evidence:"Bkav 2013\u20142015, Mahjong Logic 2019\u2014present. Twelve years since the first professional line.",strength:"strong"},{req:"3 years front-end and UI development",evidence:"Seven years leading front end at Mahjong Logic, including all UX and responsive work.",strength:"strong"},{req:"3 years testing, maintaining or launching software",evidence:"Two platform launches on the same product, plus a bot controller built to test live tables.",strength:"strong"},{req:"1 year software design and architecture",evidence:"Owned the desktop \u2192 web \u2192 React + Unity hybrid re-architecture, and the client/server API surface.",strength:"strong"},{req:"Preferred: Master's or PhD",evidence:"MSc, Uppsala University, 2018.",strength:"strong"},{req:"Preferred: 5 years data structures and algorithms",evidence:"Four years optimisation research, two publications, a book chapter, a best-paper award, three semesters as an algorithms TA.",strength:"strong"},{req:"Preferred: technical leadership",evidence:"Led a team of five for seven years \u2014 task breakdown, reviews, architecture decisions.",strength:"strong"},{req:"Preferred: accessible technologies",evidence:"No shipped product where it was my mandate. So the evidence is this build: keyboard-complete, screen-reader tested, with a live audit in the Engineering panel that is allowed to fail.",strength:"honest"},{req:"TypeScript (required for SWE III)",evidence:"This site: strict TypeScript, no framework, no runtime dependencies, size-gated in CI.",strength:"met"},{req:"Agentic coding techniques and tools",evidence:"This site was built with them, and the build log is in the Engineering panel \u2014 reviews, objections, and what changed.",strength:"met"}],g="Nam Nguyen \u2014 front-end, Uppsala. Seven years as lead front-end developer on a real-time multiplayer game client at Mahjong Logic, where he led a team of five and took the product from a native desktop app to the browser and then to a React + Unity hybrid. Before that, two years of C++ on signing hardware at Bkav. MSc Computer Science from Uppsala, plus four years of optimisation research with two publications, a book chapter and a best-paper award, and three semesters as a teaching assistant for algorithms. Swedish C1, already resident and eligible to work, 38 minutes from the Stockholm office. He wrote his application as a TypeScript web app with no dependencies, a CI-enforced size budget and a test suite you can run in the browser: ",m={siteName:"Callback",why:["A phone callback \u2014 what I am asking for.","A JS callback \u2014 what the job is.","A stand-up callback \u2014 a joke that refers back to an earlier joke."],disclaimer:"Not affiliated with, endorsed by, or built at Google. No Google marks are used. This is an homage to a product I like, built as a job application by one person in Uppsala."};export{e as a,t as b,a as c,n as d,r as e,i as f,o as g,s as h,h as i,l as j,d as k,c as l,p as m,g as n,m as o};
